//! The honest part of a G-code header: the producer line the daemon writes
//! under libslic3r's own banner, and the banner stripped for determinism
//! comparisons.

use std::fmt;

/// libslic3r's banner: `; generated by OrcaSlicer 2.3.1 on <date> at <time>`.
pub const GENERATION_BANNER_PREFIX: &str = "; generated by ";
/// How many leading lines are searched for the banner. The C++ bridge looks
/// at the same five lines.
pub const BANNER_SEARCH_LINES: usize = 5;
pub const PRODUCER_LINE_PREFIX: &str = "Protype Slicer ";
pub const MAX_PRODUCER_LINE_BYTES: usize = 128;
/// Written when the request carries no `producer_line`.
pub const DEFAULT_PRODUCER_LINE: &str =
    concat!("Protype Slicer engine ", env!("CARGO_PKG_VERSION"));

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum ProducerLineError {
    MissingBrand,
    TooLong { bytes: usize },
    ControlCharacter,
}

impl fmt::Display for ProducerLineError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Self::ControlCharacter => {
                write!(
                    f,
                    "producer_line must be one line without control characters"
                )
            }
            Self::MissingBrand => {
                write!(
                    f,
                    "producer_line must start with \"{PRODUCER_LINE_PREFIX}\""
                )
            }
            Self::TooLong { bytes } => write!(
                f,
                "producer_line is {bytes} bytes, the limit is {MAX_PRODUCER_LINE_BYTES}"
            ),
        }
    }
}

impl std::error::Error for ProducerLineError {}

/// The validated producer line: the requested one verbatim, or the engine's
/// default when none was requested.
pub fn producer_line(requested: Option<&str>) -> Result<String, ProducerLineError> {
    let Some(line) = requested else {
        return Ok(DEFAULT_PRODUCER_LINE.to_string());
    };
    if line.chars().any(char::is_control) {
        return Err(ProducerLineError::ControlCharacter);
    }
    if !line.starts_with(PRODUCER_LINE_PREFIX) {
        return Err(ProducerLineError::MissingBrand);
    }
    if line.len() > MAX_PRODUCER_LINE_BYTES {
        return Err(ProducerLineError::TooLong { bytes: line.len() });
    }
    Ok(line.to_string())
}

/// `gcode` without its generation banner (with the line break), so two
/// slices made at different times compare equal. Every other byte is kept.
pub fn without_generation_banner(gcode: &str) -> String {
    let mut offset = 0;
    for line in gcode.split_inclusive('\n').take(BANNER_SEARCH_LINES) {
        if line.starts_with(GENERATION_BANNER_PREFIX) {
            let mut kept = String::with_capacity(gcode.len() - line.len());
            kept.push_str(&gcode[..offset]);
            kept.push_str(&gcode[offset + line.len()..]);
            return kept;
        }
        offset += line.len();
    }
    gcode.to_string()
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn no_producer_line_means_the_engine_and_its_version() {
        assert_eq!(
            producer_line(None).unwrap(),
            format!("Protype Slicer engine {}", env!("CARGO_PKG_VERSION"))
        );
    }
    #[test]
    fn the_agents_producer_line_is_kept_verbatim() {
        assert_eq!(
            producer_line(Some("Protype Slicer 0.1.38")).unwrap(),
            "Protype Slicer 0.1.38"
        );
    }
    #[test]
    fn a_line_break_is_refused() {
        assert_eq!(
            producer_line(Some("Protype Slicer 0.1.38\nG28")),
            Err(ProducerLineError::ControlCharacter)
        );
    }
    #[test]
    fn another_brand_is_refused() {
        assert_eq!(
            producer_line(Some("OrcaSlicer 2.3.1")),
            Err(ProducerLineError::MissingBrand)
        );
        assert_eq!(
            producer_line(Some("")),
            Err(ProducerLineError::MissingBrand)
        );
    }
    #[test]
    fn the_line_is_capped_at_128_bytes() {
        let at_limit = format!("Protype Slicer {}", "x".repeat(113));
        assert!(producer_line(Some(&at_limit)).is_ok());
        assert_eq!(
            producer_line(Some(&format!("{at_limit}x"))),
            Err(ProducerLineError::TooLong { bytes: 129 })
        );
    }
    #[test]
    fn the_banner_line_is_dropped_and_nothing_else() {
        let gcode = "; HEADER_BLOCK_START\n; generated by OrcaSlicer 2.3.1 on 2026-11-07 at 10:00:00\n; Protype Slicer 0.1.38\nG28\n";
        assert_eq!(
            without_generation_banner(gcode),
            "; HEADER_BLOCK_START\n; Protype Slicer 0.1.38\nG28\n"
        );
    }
    #[test]
    fn a_banner_below_the_fifth_line_is_kept() {
        let gcode =
            "; a\n; b\n; c\n; d\n; e\n; generated by OrcaSlicer 2.3.1 on 2026-11-07 at 10:00:00\n";
        assert_eq!(without_generation_banner(gcode), gcode);
    }
    #[test]
    fn a_file_without_a_banner_is_unchanged() {
        assert_eq!(
            without_generation_banner("; Protype Slicer FFI G-code\nG28\n"),
            "; Protype Slicer FFI G-code\nG28\n"
        );
    }
}
